var loc = MissionManager.get_level_of_control(MissionManager._get_objective_by_id("obj_home_1"))
print("[g4] obj_home_1 level of control ", loc)
return int(loc[1]) > int(loc[2])

var hits := []
for n in tree.root.get_node("Main").find_children("*", "Label", true, false):
	if n.is_visible_in_tree() and str(n.text).begins_with("HOME_1:"):
		hits.append(str(n.text))
print("[g4] objective control readout ", hits)
return hits.has("HOME_1: Orks")
